window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[356]={"id":"356","numero":356,"titre":"Appendicite","objectifs":[{"id":"356-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la symptomatologie de l’appendicite chez l’enfant et ses différentes formes cliniques","contenu":"<p>Chez l'enfant, le diagnostic d'<span class=\"kw-clinique\">appendicite</span> est <span class=\"kw-alerte\">difficile</span> : la présentation varie fortement avec l'âge et le risque de retard diagnostique expose à la <span class=\"kw-alerte\">perforation</span>. La règle clé reste qu'il n'existe <span class=\"kw-alerte\">pas de parallélisme anatomo-clinique</span> — l'intensité des signes ne préjuge pas du degré de gravité.</p>\n\n      <h5>Symptomatologie selon l'âge</h5>\n      <table >\n        <thead>\n          <tr><th>Tranche d'âge</th><th>Présentation clinique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Nourrisson</span></td>\n            <td>Tableau <span class=\"kw-alerte\">non spécifique et trompeur</span> : <span class=\"kw-clinique\">AEG</span> ; <span class=\"kw-clinique\">fièvre</span> ; <span class=\"kw-clinique\">vomissements</span> ; <span class=\"kw-clinique\">diarrhée</span> ; <span class=\"kw-clinique\">distension abdominale</span> ; <span class=\"kw-clinique\">déshydratation</span> ; <span class=\"kw-clinique\">agitation</span> et <span class=\"kw-clinique\">insomnie</span>. <span class=\"kw-clinique\">Évolution</span> rapide vers la <span class=\"kw-alerte\">perforation</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Jeune enfant</span></td>\n            <td>Diagnostic difficile, surtout s'il ne se laisse pas examiner : <span class=\"kw-clinique\">douleur de localisation peu précise</span> ; <span class=\"kw-clinique\">fièvre modérée</span> ; <span class=\"kw-clinique\">nausées</span> et <span class=\"kw-clinique\">vomissements</span>. Pièges : <span class=\"kw-etio\">gastro-entérite aiguë</span> et <span class=\"kw-etio\">adénolymphite mésentérique</span> retardent le diagnostic.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Grand enfant</span></td>\n            <td>Symptomatologie superposable à celle de <strong>l'adulte</strong> : douleur de la <span class=\"kw-clinique\">fosse iliaque droite</span>, <span class=\"kw-clinique\">fièvre</span> modérée, défense au point de <span class=\"kw-clinique\">McBurney</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Formes cliniques selon la topographie de l'appendice</h5>\n      <p>La position de l'appendice modifie la présentation et déplace le point douloureux.</p>\n      <table >\n        <thead>\n          <tr><th>Localisation</th><th>Présentation dominante</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Latéro-caecale</span> (classique)</td><td>Douleur de la <span class=\"kw-clinique\">fosse iliaque droite</span>, défense au <span class=\"kw-clinique\">McBurney</span>.</td></tr>\n          <tr><td><span class=\"kw-def\">Rétro-caecale</span></td><td><span class=\"kw-clinique\">Psoïtis</span> franc, douleur du <span class=\"kw-clinique\">flanc droit</span>, palper bimanuel en décubitus latéral gauche.</td></tr>\n          <tr><td><span class=\"kw-def\">Pelvienne</span></td><td>Douleur hypogastrique, <span class=\"kw-clinique\">signes urinaires</span> (<span class=\"kw-clinique\">pollakiurie</span>, <span class=\"kw-clinique\">dysurie</span>), <span class=\"kw-clinique\">ténesme</span> et faux besoins.</td></tr>\n          <tr><td><span class=\"kw-def\">Méso-cœliaque</span></td><td>Tableau d'<span class=\"kw-alerte\">occlusion fébrile</span> par <span class=\"kw-clinique\">iléus</span> réflexe.</td></tr>\n          <tr><td><span class=\"kw-def\">Sous-hépatique</span></td><td>Tableau pseudo-<span class=\"kw-etio\">cholécystite</span> : douleur et défense de l'hypochondre droit.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> pédiatrique :</strong> avant <span class=\"kw-chiffre\">6 ans</span> l'<span class=\"kw-clinique\">appendicite</span> est presque toujours compliquée et, avant <span class=\"kw-chiffre\">1 an</span>, elle engage le <span class=\"kw-alerte\">pronostic vital</span>. L'imagerie et la <span class=\"kw-def\">surveillance</span> hospitalière ont une place large chez l'enfant car la clinique est prise en défaut.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — <span class=\"kw-clinique\">Douleur abdominale</span> aiguë</em></p>","frequence":1},{"id":"356-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les âges de survenue","contenu":"<p>L'<span class=\"kw-clinique\">appendicite</span> aiguë peut survenir <strong>à tout âge</strong>, mais sa fréquence suit une distribution caractéristique.</p>\n      <ul>\n        <li>Pic de fréquence : de <span class=\"kw-chiffre\">6 ans</span> à <span class=\"kw-chiffre\">30-40 ans</span>, avec une atteinte maximale chez l'<span class=\"kw-clinique\">adolescent</span> et le <span class=\"kw-clinique\">jeune adulte</span> (<span class=\"kw-chiffre\">2ᵉ et 3ᵉ décennies</span>).</li>\n        <li><span class=\"kw-alerte\">Exceptionnelle</span> avant <span class=\"kw-chiffre\">1 an</span> ; <span class=\"kw-alerte\">rare</span> avant <span class=\"kw-chiffre\">3 ans</span>.</li>\n        <li>La fréquence <strong>décroît avec l'âge</strong> au-delà de <span class=\"kw-chiffre\">40 ans</span>, du fait de l'<span class=\"kw-def\">involution des tissus lymphoïdes</span> appendiculaires.</li>\n        <li>Dans la tranche <span class=\"kw-chiffre\">20-40 ans</span>, légère <span class=\"kw-clinique\">prédominance masculine</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège des âges extrêmes :</strong> chez le <span class=\"kw-clinique\">nourrisson</span>, la pauvreté des <span class=\"kw-def\">tissus lymphoïdes</span> rend l'<span class=\"kw-clinique\">appendicite</span> <span class=\"kw-alerte\">rare mais d'emblée grave</span> ; chez le <span class=\"kw-clinique\">sujet âgé</span>, une douleur de la <span class=\"kw-clinique\">fosse iliaque droite</span> impose d'évoquer par principe un <span class=\"kw-etio\">cancer du côlon droit</span> avant de retenir une appendicite.</div>","frequence":0},{"id":"356-3","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications chez l’enfant","contenu":"<p>Chez l'enfant, l'<span class=\"kw-clinique\">appendicite</span> évolue <strong>plus vite</strong> que chez l'adulte vers la complication : la <span class=\"kw-def\">paroi appendiculaire</span> est fine et le <span class=\"kw-def\">grand omentum</span> court cloisonne mal l'infection.</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Évolution</span> rapide</strong> vers la <span class=\"kw-alerte\">perforation</span> puis la <span class=\"kw-alerte\">péritonite aiguë généralisée</span>, particulièrement chez le <span class=\"kw-clinique\">nourrisson</span>.</li>\n        <li><strong>Indice de perforation élevé</strong> : <span class=\"kw-chiffre\">70-80 %</span> des appendicites de l'enfant sont déjà <span class=\"kw-alerte\">perforées</span> au diagnostic, contre <span class=\"kw-chiffre\">≈ 30 %</span> chez le <span class=\"kw-clinique\">sujet âgé</span>.</li>\n        <li>Avant <span class=\"kw-chiffre\">6 ans</span>, l'<span class=\"kw-clinique\">appendicite</span> est <span class=\"kw-alerte\">presque toujours compliquée</span> au moment de la prise en charge.</li>\n        <li>Avant <span class=\"kw-chiffre\">1 an</span>, la complication engage le <span class=\"kw-alerte\">pronostic vital</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Message clé :</strong> <span class=\"kw-clinique\">les</span> formes compliquées sont relativement plus fréquentes dans les terrains les moins souvent touchés (<span class=\"kw-clinique\">jeune enfant</span>, <span class=\"kw-clinique\">sujet âgé</span>). Le <span class=\"kw-alerte\">retard diagnostique</span> — et non la virulence — est le principal moteur de la <span class=\"kw-alerte\">perforation</span> pédiatrique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 357 — <span class=\"kw-clinique\">Péritonite</span> aiguë</em></p>","frequence":0},{"id":"356-4","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’intérêt et les limites des examens complémentaires","contenu":"<p>Le diagnostic d'<span class=\"kw-clinique\">appendicite</span> reste <strong>avant tout clinique</strong>. <span class=\"kw-clinique\">Les</span> examens complémentaires servent à <strong>conforter</strong> le diagnostic, <strong>éliminer un <span class=\"kw-def\">diagnostic différentiel</span></strong> ou <strong>dépister une complication</strong> — jamais à remplacer l'examen.</p>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Intérêt</th><th>Limites</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\">NFS</span></td>\n            <td>Marqueur le plus souvent perturbé : <span class=\"kw-bio\">hyperleucocytose à PNN</span> dans plus de <span class=\"kw-chiffre\">80 %</span> des cas.</td>\n            <td>Peut être normale dans <span class=\"kw-clinique\">les</span> formes débutantes ; non spécifique.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">CRP</span></td>\n            <td>Témoigne d'une inflammation évoluant depuis quelques heures.</td>\n            <td><span class=\"kw-bio\">Normale dans 50 %</span> des cas (<span class=\"kw-clinique\">appendicite</span> catarrhale débutante).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Bandelette urinaire</span></td>\n            <td>Élimine une <span class=\"kw-etio\">infection urinaire</span>.</td>\n            <td>Une <span class=\"kw-bio\">leucocyturie</span> modérée peut accompagner une <span class=\"kw-clinique\">appendicite</span> pelvienne (piège).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">β-hCG</span></td>\n            <td><strong>Systématique</strong> chez la femme en âge de procréer : écarte une <span class=\"kw-etio\">grossesse extra-utérine</span>.</td>\n            <td>Ne renseigne pas sur l'appendice lui-même.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Échographie abdominale</span></td>\n            <td>Examen de <strong>1ʳᵉ intention</strong> ; <span class=\"kw-bio\">Se ≈ 80 %</span> ; non irradiante.</td>\n            <td>Opérateur-dépendante ; mise en défaut chez l'<span class=\"kw-clinique\">obèse</span> et si appendice <span class=\"kw-clinique\">rétro-caecal</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">TDM abdomino-pelvienne injectée</span></td>\n            <td>Meilleure performance (<span class=\"kw-bio\">Se et Sp &gt; 90-95 %</span>) ; précise <span class=\"kw-clinique\">les</span> complications.</td>\n            <td>Irradiante ; réservée au doute, à la complication, au sujet âgé ou obèse.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">IRM abdominale</span></td>\n            <td>Alternative non irradiante chez la <span class=\"kw-clinique\">femme enceinte</span>.</td>\n            <td>Peu disponible en <span class=\"kw-alerte\">urgence</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Examens à ne pas demander :</strong> l'<span class=\"kw-imagerie\">ASP</span> n'a plus aucune place dans le bilan d'<span class=\"kw-clinique\">appendicite</span> ; le dosage de <span class=\"kw-bio\">procalcitonine</span> n'est pas recommandé car il n'améliore pas la précision diagnostique.</div>","frequence":0},{"id":"356-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge","contenu":"<p>L'<span class=\"kw-clinique\">appendicite</span> aiguë confirmée est une <span class=\"kw-alerte\">urgence chirurgicale</span> : le traitement est <strong>toujours chirurgical</strong>, en raison du risque d'<span class=\"kw-clinique\">évolution</span> vers une <span class=\"kw-alerte\">forme compliquée</span>.</p>\n\n      <h5>Délais de prise en charge</h5>\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>Délai de l'intervention</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Absence de <span class=\"kw-clinique\">signe de gravité</span></td><td><span class=\"kw-def\">Appendicectomie</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 24 h</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Signes de gravité</span> ou <span class=\"kw-clinique\">terrain fragile</span></td><td><span class=\"kw-def\">Appendicectomie</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 4 h</span></td></tr>\n        </tbody>\n      </table>\n\n      <h5>Mesures pré-opératoires</h5>\n      <ul>\n        <li><span class=\"kw-clinique\">Patient à jeun</span> en attendant le bloc.</li>\n        <li><span class=\"kw-ttt\">Antibiothérapie probabiliste</span> dirigée contre <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">germes digestifs</span>.</li>\n        <li><span class=\"kw-ttt\">Antalgiques</span> : <span class=\"kw-ttt\">paracétamol</span> ou <span class=\"kw-ttt\">phloroglucinol</span>.</li>\n        <li><span class=\"kw-ttt\">Hydratation par voie IV</span> et correction des <span class=\"kw-bio\">troubles hydro-électrolytiques</span>.</li>\n        <li><span class=\"kw-clinique\">Consultation d'anesthésie en urgence</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong><span class=\"kw-clinique\">Évolution</span> de la doctrine :</strong> l'<span class=\"kw-def\">appendicectomie</span> n'est plus systématique devant toute douleur de la <span class=\"kw-clinique\">fosse iliaque droite</span>. Elle n'est décidée qu'<strong>après une démarche diagnostique</strong> structurée (<span class=\"kw-clinique\">clinique</span>, <span class=\"kw-bio\">biologie</span>, <span class=\"kw-imagerie\">imagerie</span>).</div>","frequence":1},{"id":"356-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la symptomatologie de l’appendicite chez le nourrisson","contenu":"<p>Chez le <span class=\"kw-clinique\">nourrisson</span>, la présentation est <span class=\"kw-alerte\">non spécifique et trompeuse</span>. C'est ce qui fait toute la <span class=\"kw-alerte\">gravité</span> de la pathologie à cet âge : le diagnostic est porté <span class=\"kw-alerte\">tardivement</span>.</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Altération de l'état général</span> (<span class=\"kw-clinique\">AEG</span>).</li>\n        <li><span class=\"kw-clinique\">Fièvre</span> et <span class=\"kw-clinique\">vomissements</span>.</li>\n        <li><span class=\"kw-clinique\">Diarrhée</span> — qui oriente faussement vers une <span class=\"kw-etio\">gastro-entérite</span>.</li>\n        <li><span class=\"kw-clinique\">Distension abdominale</span> et <span class=\"kw-clinique\">déshydratation</span>.</li>\n        <li><span class=\"kw-clinique\">Agitation</span> et <span class=\"kw-clinique\">insomnie</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Conséquence :</strong> <span class=\"kw-clinique\">évolution</span> rapide vers la <span class=\"kw-alerte\">perforation</span> et la <span class=\"kw-alerte\">péritonite aiguë généralisée</span>. L'<span class=\"kw-imagerie\">échographie</span> et la <span class=\"kw-bio\">biologie</span> sont très utiles puisque l'examen clinique est ici peu contributif ; une <span class=\"kw-clinique\">surveillance hospitalière</span> de quelques jours peut précéder la décision opératoire.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — <span class=\"kw-clinique\">Douleur abdominale</span> aiguë</em></p>","frequence":0},{"id":"356-7","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’appendicite aiguë","contenu":"<p>L'<span class=\"kw-def\">appendicite aiguë</span> est une <strong>inflammation aiguë de l'appendice vermiforme</strong>, le plus souvent secondaire à une <strong>obstruction de la lumière appendiculaire</strong>.</p>\n\n      <h5>Causes de l'obstruction appendiculaire</h5>\n      <table >\n        <thead>\n          <tr><th>Cause</th><th>Mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Stercolithe</span></td><td>Concrétion dure de matières fécales obstruant la lumière (cause la plus classique).</td></tr>\n          <tr><td><span class=\"kw-etio\">Hyperplasie lymphoïde</span></td><td>Réaction des follicules lymphoïdes à un épisode <span class=\"kw-etio\">viral</span> ou bactérien du tube digestif.</td></tr>\n          <tr><td><span class=\"kw-etio\">Infection parasitaire</span></td><td>Obstruction mécanique (ascaris).</td></tr>\n          <tr><td><span class=\"kw-etio\">Sténose inflammatoire</span></td><td>Épaississement pariétal dans la maladie de <span class=\"kw-etio\">Crohn</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Tumeur</span></td><td>Occlusion par une tumeur, le plus souvent <span class=\"kw-etio\">carcinoïde</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h5><span class=\"kw-def\">Physiopathologie</span> en 4 temps</h5>\n      <ol>\n        <li>L'obstruction entraîne une <strong>pullulation microbienne</strong> responsable de l'infection de l'appendice.</li>\n        <li>L'inflammation s'étend progressivement aux <strong>4 couches pariétales</strong> : c'est l'<span class=\"kw-def\">appendicite suppurée</span>.</li>\n        <li>La distension comprime la vascularisation et entraîne une <span class=\"kw-alerte\">ischémie artérielle</span>.</li>\n        <li>En l'absence de traitement, l'<span class=\"kw-clinique\">évolution</span> se fait vers la <span class=\"kw-alerte\">gangrène</span> puis la <span class=\"kw-alerte\">perforation</span>.</li>\n      </ol>\n\n      <h5>Rappel anatomique</h5>\n      <table >\n        <thead>\n          <tr><th>Élément</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Organe</strong></td><td><span class=\"kw-clinique\">Diverticule</span> appendu au <strong>cæcum</strong>, riche en <span class=\"kw-def\">tissu lymphoïde</span> ; longueur moyenne <span class=\"kw-chiffre\">8 cm</span> (<span class=\"kw-chiffre\">2 à 20 cm</span>), épaisseur <span class=\"kw-chiffre\">4 à 8 mm</span>.</td></tr>\n          <tr><td><strong>Paroi en 4 couches</strong></td><td>Séreuse externe ; musculeuse ; sous-muqueuse (riche en <span class=\"kw-def\">follicules lymphoïdes</span>) ; muqueuse délimitant la lumière.</td></tr>\n          <tr><td><strong>Vascularisation</strong></td><td><span class=\"kw-def\">Artère appendiculaire</span>, branche terminale de l'artère iléo-colique — vascularisation de <strong>type terminal</strong>, d'où le risque d'<span class=\"kw-alerte\">ischémie</span>.</td></tr>\n          <tr><td><strong>Implantation</strong></td><td>Zone de convergence des <strong>3 bandelettes musculaires longitudinales</strong> du côlon droit, à environ <span class=\"kw-chiffre\">2 cm</span> de la valvule iléo-cæcale.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>Formes anatomopathologiques :</strong> formes non compliquées — <span class=\"kw-def\">catarrhale</span> (muqueuse seule), <span class=\"kw-def\">suppurée</span>, <span class=\"kw-def\">gangréneuse</span> ; formes compliquées — <span class=\"kw-alerte\">abcès</span>, <span class=\"kw-clinique\">plastron</span>, <span class=\"kw-alerte\">péritonite</span>.</div>","frequence":0},{"id":"356-8","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la fréquence, l’âge de survenue et la morbi-mortalité et la mortalité de l’appendicite","contenu":"<p>L'<span class=\"kw-clinique\">appendicite</span> aiguë est l'<span class=\"kw-def\">urgence abdominale la plus fréquente</span>.</p>\n      <ul>\n        <li><strong>Fréquence :</strong> concerne environ <span class=\"kw-chiffre\">7 %</span> de la population dans <span class=\"kw-clinique\">les</span> pays occidentaux, dont <span class=\"kw-chiffre\">20 %</span> de <span class=\"kw-alerte\">formes compliquées</span>.</li>\n        <li><strong>Volume d'activité :</strong> environ <span class=\"kw-chiffre\">90 000 à 130 000</span> <span class=\"kw-def\">appendicectomies</span> par an en France (<span class=\"kw-chiffre\">≈ 1,4 / 1 000 habitants</span>), soit <span class=\"kw-chiffre\">≈ 30 %</span> des interventions de <span class=\"kw-ttt\">chirurgie</span> digestive.</li>\n        <li><strong>Âge :</strong> pic de fréquence de <span class=\"kw-chiffre\">6 ans</span> à <span class=\"kw-chiffre\">30-40 ans</span> ; exceptionnelle avant <span class=\"kw-chiffre\">1 an</span>, rare avant <span class=\"kw-chiffre\">3 ans</span> ; décroît ensuite avec l'âge.</li>\n      </ul>\n\n      <h5>Morbi-<span class=\"kw-def\">mortalité</span></h5>\n      <table >\n        <thead>\n          <tr><th>Indicateur</th><th>Valeur</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Mortalité</span> post-opératoire globale</td><td><span class=\"kw-chiffre\">&lt; 0,5 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span> — forme non compliquée</td><td><span class=\"kw-chiffre\">≈ 0,1 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span> — <span class=\"kw-alerte\">perforation appendiculaire</span></td><td><span class=\"kw-chiffre\">≈ 1,5 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">Morbidité</span> globale des <span class=\"kw-def\">appendicectomies</span></td><td><span class=\"kw-chiffre\">≈ 10 %</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong><span class=\"kw-clinique\">Évolution</span> des pratiques :</strong> l'<span class=\"kw-def\">appendicectomie</span> était autrefois quasi systématique devant toute douleur de la <span class=\"kw-clinique\">fosse iliaque droite</span> ; elle n'est aujourd'hui réalisée qu'au terme d'une démarche diagnostique.</div>","frequence":0},{"id":"356-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes d’appel et les caractéristiques de la douleur appendiculaire typique","contenu":"<p>Le tableau typique de l'<span class=\"kw-clinique\">appendicite</span> aiguë associe une <strong>douleur</strong> caractéristique, des <strong>signes digestifs</strong> et un <strong>fébricule</strong>, confirmés par l'examen de la <span class=\"kw-clinique\">fosse iliaque droite</span>.</p>\n\n      <h5>Caractéristiques de la douleur appendiculaire</h5>\n      <table >\n        <thead>\n          <tr><th>Caractère</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Mode de début</td><td><span class=\"kw-clinique\">Brutal</span>.</td></tr>\n          <tr><td>Topographie</td><td>Peut débuter en région <span class=\"kw-clinique\">épigastrique</span> ou <span class=\"kw-clinique\">péri-ombilicale</span>, puis <strong>migre en fosse iliaque droite</strong> en quelques heures.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Irradiation</span></td><td>Absente.</td></tr>\n          <tr><td>Horaire</td><td><span class=\"kw-clinique\">Permanente</span>, d'intensité <strong>croissante</strong> sur <span class=\"kw-clinique\">les</span> premières <span class=\"kw-chiffre\">24 h</span>.</td></tr>\n          <tr><td>Type</td><td>À type de <span class=\"kw-clinique\">torsion</span> ou de <span class=\"kw-clinique\">crampe</span>.</td></tr>\n          <tr><td>Facteurs aggravants</td><td>Majorée par <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">mouvements</span>, la <span class=\"kw-clinique\">toux</span> et le <span class=\"kw-clinique\">cloche-pied droit</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Signes associés</h5>\n      <ul>\n        <li><strong>Signes digestifs :</strong> <span class=\"kw-clinique\">nausées</span> ; <span class=\"kw-clinique\">vomissements</span> ; <span class=\"kw-clinique\">inappétence</span> ; <span class=\"kw-clinique\">diarrhée</span> rare.</li>\n        <li><strong>Signes généraux :</strong> <span class=\"kw-clinique\">fébricule</span> à <span class=\"kw-chiffre\">37,5-38,5 °C</span> (dans <span class=\"kw-chiffre\">60 %</span> des cas), parfois absent ; signes de <span class=\"kw-clinique\">déshydratation</span> dans <span class=\"kw-clinique\">les</span> formes évoluées (<span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">pli cutané</span>, <span class=\"kw-clinique\">langue saburrale</span>).</li>\n      </ul>\n\n      <h5>Examen physique de la fosse iliaque droite</h5>\n      <p><strong>Inspection :</strong> rechercher l'<span class=\"kw-clinique\">absence de cicatrice d'appendicectomie</span> — un patient déjà appendicectomisé doit faire chercher un autre diagnostic.</p>\n      <table >\n        <thead>\n          <tr><th>Manœuvre</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Point de McBurney</span></td><td>Douleur provoquée (<span class=\"kw-clinique\">sensibilité</span> ou <span class=\"kw-clinique\">défense</span>) au 1/3 externe de la ligne reliant l'épine iliaque antéro-supérieure droite à l'ombilic.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Signe de Blumberg</span></td><td>Douleur en FID à la <span class=\"kw-clinique\">décompression brutale de la FID</span> (inconstant).</td></tr>\n          <tr><td><span class=\"kw-clinique\">Signe de Rovsing</span></td><td>Douleur en FID provoquée par la <span class=\"kw-clinique\">compression de la fosse iliaque gauche</span> (inconstant).</td></tr>\n          <tr><td><span class=\"kw-clinique\">Psoïtis</span></td><td><span class=\"kw-clinique\">Boiterie</span>, cuisse droite fléchie en position <span class=\"kw-ttt\">antalgique</span> ; l'extension de la cuisse sur le bassin majore la douleur.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Heel drop test</span></td><td><span class=\"kw-clinique\">Douleur abdominale</span> déclenchée par la retombée sur <span class=\"kw-clinique\">les</span> talons — plus précis que la défense pour l'irritation péritonéale.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Toucher rectal</span></td><td>Douleur latéralisée à droite (« cri du Douglas ») ; le toucher vaginal est déconseillé chez l'enfant.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"appendix-figure\">\n        <svg viewBox=\"0 0 440 252\" role=\"img\" aria-label=\"Localisation du point de McBurney sur la ligne ombilico-iliaque droite\">\n          <path class=\"af-body\" d=\"M62 34 Q220 14 378 34 Q418 124 378 222 Q220 244 62 222 Q22 124 62 34 Z\"/>\n          <line class=\"af-line\" x1=\"210\" y1=\"120\" x2=\"330\" y2=\"197\"/>\n          <circle class=\"af-mark\" cx=\"210\" cy=\"120\" r=\"5\"/>\n          <text class=\"af-lbl\" x=\"210\" y=\"106\" text-anchor=\"middle\">Ombilic</text>\n          <circle class=\"af-mark\" cx=\"330\" cy=\"197\" r=\"5\"/>\n          <text class=\"af-lbl\" x=\"356\" y=\"208\" text-anchor=\"middle\">ÉIAS droite</text>\n          <circle class=\"af-mcburney\" cx=\"290\" cy=\"171\" r=\"9\"/>\n          <text class=\"af-mcb\" x=\"290\" y=\"150\" text-anchor=\"middle\">Point de McBurney</text>\n          <text class=\"af-sub\" x=\"220\" y=\"240\" text-anchor=\"middle\">Au 1/3 externe de la ligne ombilic – épine iliaque antéro-supérieure droite</text>\n        </svg>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — <span class=\"kw-clinique\">Douleur abdominale</span> aiguë</em></p>","frequence":2},{"id":"356-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques et biologiques en défaveur d’une appendicite aiguë","contenu":"<p>Certains signes négatifs permettent d'<strong>écarter</strong> une <span class=\"kw-clinique\">appendicite</span> et d'orienter vers un <span class=\"kw-def\">diagnostic différentiel</span> — étape essentielle pour ne pas opérer à tort.</p>\n\n      <div class=\"callout callout-info\"><strong>Tétrade en défaveur (recommandations HAS 2012) :</strong> en l'absence concomitante de <span class=\"kw-clinique\">fièvre</span>, de <span class=\"kw-clinique\">défense en FID</span>, d'<span class=\"kw-bio\">hyperleucocytose</span> et d'élévation de la <span class=\"kw-bio\">CRP</span> (&lt; <span class=\"kw-chiffre\">8 mg/L</span>), le diagnostic d'<span class=\"kw-clinique\">appendicite</span> peut être <strong>écarté</strong>.</div>\n\n      <h5><span class=\"kw-def\">Score</span> d'Alvarado — aide à l'orientation</h5>\n      <p>Aucun <span class=\"kw-def\">score</span> n'est validé pour la pratique courante, mais le score d'Alvarado constitue une <strong>aide à l'orientation</strong> de la prise en charge.</p>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Points</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Douleur migrant en FID</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Anorexie</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Nausées / vomissements</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Température &gt; 37,3 °C</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Défense en FID</span></td><td><span class=\"kw-chiffre\">2</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Défense à la percussion de la FID</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Hyperleucocytose &gt; 10 000/mm³</span></td><td><span class=\"kw-chiffre\">2</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Neutrophiles &gt; 75 %</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><span class=\"kw-chiffre\">0–4</span> : <span class=\"kw-clinique\">appendicite</span> <strong>improbable</strong>.</li>\n        <li><span class=\"kw-chiffre\">5–6</span> : <span class=\"kw-clinique\">appendicite</span> <strong>possible</strong>.</li>\n        <li><span class=\"kw-chiffre\">7–8</span> : <span class=\"kw-clinique\">appendicite</span> <strong>probable</strong>.</li>\n        <li><span class=\"kw-chiffre\">9–10</span> : <span class=\"kw-clinique\">appendicite</span> <strong>très probable</strong>.</li>\n      </ul>\n\n      <h5>Principaux diagnostics différentiels</h5>\n      <table >\n        <thead>\n          <tr><th>Contexte</th><th>Diagnostics à évoquer</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Enfant</span></td>\n            <td><strong>Adénolymphite mésentérique</strong> : cause la plus fréquente de syndrome pseudo-appendiculaire (antécédent de rhino-pharyngite, <span class=\"kw-clinique\">fièvre</span> &gt;<span class=\"kw-chiffre\"> 39 °C</span>, douleur sans défense) ; <strong>invagination intestinale aiguë</strong> ; <strong>gastro-entérite aiguë</strong>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Femme en âge de procréer</span></td>\n            <td><span class=\"kw-etio\">Salpingite</span> — <span class=\"kw-clinique\">douleurs hypogastriques</span> + <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span> + pertes vaginales + douleur au <span class=\"kw-alerte\">TV</span> ; écho pelvienne : <span class=\"kw-imagerie\">épaississement</span> et <span class=\"kw-imagerie\">aspect en roue dentée</span>. <span class=\"kw-etio\">Torsion d'annexe</span> ; <span class=\"kw-etio\">grossesse extra-utérine</span> ; <span class=\"kw-etio\">ovulation douloureuse</span> ; <span class=\"kw-etio\">endométriose</span> — d'où la <span class=\"kw-bio\">β-hCG</span> et l'examen gynécologique systématiques.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Urinaire</span></td>\n            <td><span class=\"kw-etio\">Colique néphrétique</span> ; <span class=\"kw-etio\">pyélonéphrite aiguë</span> — la <span class=\"kw-bio\">bandelette urinaire</span> oriente.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Digestif</span></td>\n            <td><strong><span class=\"kw-clinique\">Diverticulite</span> de Meckel</strong> ; <strong>appendalgite</strong> (torsion d'une frange épiploïque colique) ; <span class=\"kw-etio\">diverticulite du côlon droit</span> ou <span class=\"kw-etio\">diverticulite sigmoïdienne</span> avec boucle localisée en FID ; <span class=\"kw-etio\">cholécystite aiguë</span> ; <span class=\"kw-etio\">MICI</span> (Crohn ++) ; <span class=\"kw-etio\">tumeur du côlon droit</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Trois pièges à connaître</h5>\n      <ul>\n        <li><strong>Adénolymphite mésentérique :</strong> <span class=\"kw-clinique\">fièvre</span> élevée et douleur de FID <span class=\"kw-clinique\">sans défense</span> ; l'<span class=\"kw-imagerie\">échographie</span> montre des <span class=\"kw-clinique\">adénopathies</span> mésentériques et un appendice normal.</li>\n        <li><strong><span class=\"kw-clinique\">Diverticule</span> de Meckel :</strong> diverticule du bord antimésentérique de l'iléon terminal, pouvant contenir une muqueuse gastrique ectopique ; diagnostic souvent peropératoire.</li>\n        <li><strong>Appendalgite :</strong> torsion d'une frange épiploïque ; douleur de FID <span class=\"kw-clinique\">sans hyperleucocytose ni signe infectieux</span> ; traitement par anti-inflammatoires.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — <span class=\"kw-clinique\">Douleur abdominale</span> aiguë · 287 — Diverticulose colique - <span class=\"kw-clinique\">diverticulite</span> aiguë · 277 — Lithiase biliaire · 265 — Lithiase urinaire · 161 — <span class=\"kw-etio\">Infection urinaire</span> · 25 — <span class=\"kw-ci\">Grossesse</span> extra-utérine · 282 — <span class=\"kw-etio\">MICI</span></em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/meckel-diverticulum-3?lang=us","label":"Radiopaedia : Meckel diverticulum 3"}]},{"id":"356-11","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les variations anatomiques de l’appendice et les formes cliniques qui en résultent","contenu":"<p><span class=\"kw-clinique\">Les</span> variations de position de l'<span class=\"kw-def\">appendice vermiforme</span> (et du cæcum) sont fréquentes et expliquent l'extrême variabilité des présentations cliniques.</p>\n\n      <h5>Fréquence des localisations anatomiques</h5>\n      <table >\n        <thead>\n          <tr><th>Localisation</th><th>Fréquence</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Latéro-caecale</span> (face postéro-médiale du cæcum)</td><td><span class=\"kw-chiffre\">≈ 70 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">Rétro-caecale</span></td><td><span class=\"kw-chiffre\">≈ 25 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">Pelvienne</span></td><td><span class=\"kw-chiffre\">≈ 5 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">Méso-cœliaque</span> (pré- ou rétro-iléale) et <span class=\"kw-def\">sous-hépatique</span></td><td>Rares</td></tr>\n          <tr><td>Fosse iliaque gauche (<span class=\"kw-def\">mésentère commun</span>)</td><td>Exceptionnelle</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Formes cliniques résultant de la topographie</h5>\n      <table >\n        <thead>\n          <tr><th>Localisation</th><th>Présentation</th><th>Confirmation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Rétro-caecale</span></td>\n            <td><span class=\"kw-clinique\">Psoïtis</span> franc ; douleur peu marquée en FID, plutôt en <span class=\"kw-clinique\">flanc droit</span> ; palper bimanuel en décubitus latéral gauche.</td>\n            <td><span class=\"kw-imagerie\">TDM injectée</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Pelvienne</span></td>\n            <td>Douleur hypogastrique droite ; <span class=\"kw-clinique\">signes urinaires</span> (<span class=\"kw-clinique\">pollakiurie</span>, <span class=\"kw-clinique\">dysurie</span>) ; <span class=\"kw-clinique\">ténesme rectal</span> et faux besoins ; toucher rectal et vaginal contributifs.</td>\n            <td><span class=\"kw-imagerie\">Échographie pelvienne</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Méso-cœliaque</span></td>\n            <td>Tableau d'<span class=\"kw-alerte\">occlusion fébrile</span> par <span class=\"kw-clinique\">iléus</span> réflexe au <span class=\"kw-def\">contact</span> des anses.</td>\n            <td><span class=\"kw-imagerie\">Imagerie</span> voire intervention</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Sous-hépatique</span></td>\n            <td>Tableau pseudo-<span class=\"kw-etio\">cholécystite</span> : douleur et défense de l'hypochondre droit avec <span class=\"kw-clinique\">fièvre</span>.</td>\n            <td><span class=\"kw-imagerie\">Échographie</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Piège :</strong> la forme méso-cœliaque réalise un véritable tableau de syndrome occlusif fébrile qui peut faire errer le diagnostic.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 354 — Syndrome occlusif</em></p>","frequence":0},{"id":"356-12","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les particularités de la présentation clinique de l’appendicite chez la femme enceinte","contenu":"<p>Chez la <span class=\"kw-clinique\">femme enceinte</span>, la présentation dépend du <strong>terme</strong> de la <span class=\"kw-ci\">grossesse</span>, l'utérus gravide refoulant progressivement l'appendice.</p>\n      <table >\n        <thead>\n          <tr><th>Terme</th><th>Présentation clinique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">1ᵉʳ trimestre</span></td>\n            <td>Examen clinique <strong>non modifié</strong> : tableau d'<span class=\"kw-clinique\">appendicite</span> en situation normale.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">2ᵉ et 3ᵉ trimestres</span></td>\n            <td>L'<span class=\"kw-clinique\">augmentation du volume utérin</span> <strong>refoule l'<span class=\"kw-def\">appendice</span> vers l'<span class=\"kw-clinique\">hypochondre droit</span></strong> (vers le <strong>haut</strong>, le <strong>dehors</strong> et l'<strong>arrière</strong>) : <span class=\"kw-clinique\">douleur ascensionnée</span> ou <span class=\"kw-clinique\">diffuse</span> ; <span class=\"kw-clinique\">contractures utérines</span> parfois au premier plan ; <span class=\"kw-clinique\">absence de défense</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Diagnostics différentiels :</strong> <span class=\"kw-etio\">infection urinaire</span> ; <span class=\"kw-etio\">cholécystite</span>.</li>\n        <li><strong>Imagerie :</strong> l'<span class=\"kw-imagerie\">IRM abdominale</span> est <span class=\"kw-imagerie\">préférée à la TDM</span> (caractère <span class=\"kw-imagerie\">non irradiant</span>).</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège :</strong> l'<span class=\"kw-clinique\">absence de défense</span> aux 2ᵉ et 3ᵉ trimestres ne doit jamais faire éliminer une <span class=\"kw-clinique\">appendicite</span> — la <span class=\"kw-def\">position ectopique de l'appendice</span> masque <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">signes pariétaux</span> classiques.</div>","frequence":0},{"id":"356-13","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les particularités de la présentation clinique de l’appendicite chez le sujet âgé","contenu":"<p>Chez le <span class=\"kw-clinique\">sujet âgé</span>, l'<span class=\"kw-def\">appendicite</span> est <span class=\"kw-clinique\">plus rare</span> mais souvent <span class=\"kw-alerte\">diagnostiquée tardivement</span>, à un <span class=\"kw-alerte\">stade compliqué</span>.</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Symptômes moins francs</span> que chez l'<span class=\"kw-clinique\">adulte jeune</span>.</li>\n        <li><span class=\"kw-clinique\">Évolution plus torpide</span>.</li>\n        <li><span class=\"kw-clinique\">Iléus</span> fréquemment présent.</li>\n        <li><span class=\"kw-alerte\">Indice de perforation élevé</span> (<span class=\"kw-chiffre\">≈ 30 %</span>) du fait du <span class=\"kw-alerte\">retard diagnostique</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Règle absolue :</strong> devant une douleur de la <span class=\"kw-clinique\">fosse iliaque droite</span> chez un <span class=\"kw-clinique\">sujet âgé</span>, il faut <strong>éliminer impérativement un</strong> <span class=\"kw-etio\">cancer du côlon droit</span> avant de retenir une <span class=\"kw-def\">appendicite</span>. La <span class=\"kw-imagerie\">TDM injectée</span> est volontiers réalisée d'emblée.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum</em></p>","frequence":0},{"id":"356-14","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques des trois principales complications de l’appendicite : abcès, plastron, péritonite.","contenu":"<p>Environ <span class=\"kw-chiffre\">20 %</span> des appendicites se présentent ou évoluent vers une forme compliquée. Trois complications sont à connaître : le <strong>plastron</strong>, l'<strong><span class=\"kw-clinique\">abcès</span></strong> et la <strong><span class=\"kw-clinique\">péritonite</span></strong>.</p>\n\n      <h5>Tableau comparatif plastron / <span class=\"kw-clinique\">abcès</span></h5>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Plastron appendiculaire</th><th><span class=\"kw-clinique\">Abcès</span> appendiculaire</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Signes généraux</td><td><span class=\"kw-clinique\">Fièvre modérée</span></td><td>Plus marqués : <span class=\"kw-clinique\">AEG</span>, <span class=\"kw-clinique\">fièvre &gt; 38,5 °C</span> en plateau, sans <span class=\"kw-clinique\">frissons</span></td></tr>\n          <tr><td>Symptômes</td><td>Douleur en FID</td><td>Douleur et défense en FID ; <span class=\"kw-clinique\">syndrome subocclusif</span> par <span class=\"kw-clinique\">iléus</span> réflexe</td></tr>\n          <tr><td>Palpation</td><td><span class=\"kw-clinique\">Masse douloureuse</span> et <span class=\"kw-clinique\">empâtement</span> de la FID ; peau rouge et chaude ; reste de l'abdomen souple</td><td><span class=\"kw-clinique\">Empâtement</span> ou <span class=\"kw-clinique\">masse</span> douloureuse de la FID pouvant s'étendre au flanc droit ; reste de l'abdomen souple</td></tr>\n          <tr><td>Biologie</td><td><span class=\"kw-bio\">Hyperleucocytose à PNN</span> ; <span class=\"kw-bio\">≥ 3 hémocultures</span> si signes <span class=\"kw-etio\">infectieux</span> patents</td><td><span class=\"kw-bio\">Hyperleucocytose marquée</span> (&gt; <span class=\"kw-chiffre\">15 000/mm³</span>)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM</span></td><td><span class=\"kw-clinique\">Masse</span> de la FID engainant <span class=\"kw-clinique\">les</span> anses grêles, signes inflammatoires intenses</td><td><span class=\"kw-imagerie\">Collection liquidienne</span> à coque rehaussée, réaction <span class=\"kw-etio\">inflammatoire</span> des mésos, <span class=\"kw-clinique\">iléus</span> réflexe</td></tr>\n          <tr><td><span class=\"kw-clinique\">Évolution</span> non traitée</td><td><span class=\"kw-alerte\">Risque d'abcédation</span></td><td><span class=\"kw-alerte\">Rupture</span> → <span class=\"kw-alerte\">péritonite généralisée</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Antibiothérapie</span></td><td><span class=\"kw-ttt\">ATB probabiliste puis adaptée</span> pendant <span class=\"kw-chiffre\">7 jours</span></td><td><span class=\"kw-ttt\">ATB probabiliste puis adaptée</span> pendant <span class=\"kw-chiffre\">7 jours</span></td></tr>\n          <tr><td>Geste</td><td>Aucun geste local</td><td><span class=\"kw-imagerie\">Drainage</span> percutané radiologique (grande taille) ou chirurgical (petite taille / signes péritonéaux)</td></tr>\n          <tr><td>Appendicectomie</td><td>Différée, à <span class=\"kw-chiffre\">3 mois</span></td><td>Différée, à <span class=\"kw-chiffre\">3 mois</span></td></tr>\n        </tbody>\n      </table>\n\n      <h5>Modes d'installation de la <span class=\"kw-clinique\">péritonite</span> appendiculaire</h5>\n      <table >\n        <thead>\n          <tr><th>Mode</th><th>Mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>En 1 temps</strong></td><td>Diffusion de l'infection <strong>sans espace libre</strong> — <span class=\"kw-clinique\">péritonite</span> <span class=\"kw-alerte\">inaugurale généralisée d'emblée</span>.</td></tr>\n          <tr><td><strong>En 2 temps</strong></td><td><span class=\"kw-alerte\">Rupture d'un abcès appendiculaire</span> non pris en charge.</td></tr>\n          <tr><td><strong>En 3 temps</strong></td><td>Constitution d'un <span class=\"kw-clinique\">plastron</span> → <span class=\"kw-clinique\">évolution</span> vers un <span class=\"kw-alerte\">abcès</span> → <span class=\"kw-alerte\">rupture</span> secondaire.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-clinique\">Péritonite</span> appendiculaire généralisée — <span class=\"kw-alerte\">urgence</span> chirurgicale absolue.</strong>\n        <ul>\n          <li><strong>Clinique :</strong> <span class=\"kw-clinique\">altération de l'état général</span> (<span class=\"kw-clinique\">faciès gris, terreux</span>) ; douleur intense et généralisée avec <span class=\"kw-clinique\">défense généralisée voire contracture</span> ; <span class=\"kw-clinique\">fièvre &gt; 38,5 °C</span> ; toucher rectal douloureux au cul-de-sac de Douglas.</li>\n          <li><strong>Signe négatif clé :</strong> <span class=\"kw-alerte\">pas de pneumopéritoine</span> — la matité pré-hépatique est conservée.</li>\n          <li><strong>CAT :</strong> devant un tableau typique, aucun autre examen n'est nécessaire ; toilette péritonéale + <span class=\"kw-ttt\">drainage</span> + appendicectomie en <span class=\"kw-alerte\">urgence</span> (cœlioscopie ou laparotomie) ; <span class=\"kw-ttt\">antibiothérapie</span> probabiliste puis adaptée pendant <span class=\"kw-chiffre\">5 à 7 jours</span>.</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 357 — <span class=\"kw-clinique\">Péritonite</span> aiguë · 354 — Syndrome occlusif</em></p>","frequence":1},{"id":"356-15","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens biologiques à demander et leurs limites","contenu":"<p>Le bilan <span class=\"kw-ttt\">biologique</span> de l'<span class=\"kw-clinique\">appendicite</span> est <strong>simple</strong> et son apport reste limité : il conforte le diagnostic et écarte certains différentiels, mais ne le pose jamais à lui seul.</p>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Résultat attendu</th><th>Limite</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\">NFS</span></td>\n            <td><span class=\"kw-bio\">Hyperleucocytose à PNN</span> (<span class=\"kw-chiffre\">&gt; 10 000/mm³</span>) dans plus de <span class=\"kw-chiffre\">80 %</span> des cas — marqueur le plus souvent perturbé.</td>\n            <td>Peut être <span class=\"kw-bio\">normale</span> dans <span class=\"kw-clinique\">les</span> formes débutantes ; <span class=\"kw-bio\">non spécifique</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">CRP</span></td>\n            <td>Élevée si l'inflammation évolue depuis quelques heures.</td>\n            <td><span class=\"kw-bio\">Normale dans 50 %</span> des cas (<span class=\"kw-def\">appendicite catarrhale</span> débutante).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Bandelette urinaire</span></td>\n            <td>Utile pour <strong>éliminer une</strong> <span class=\"kw-etio\">infection urinaire</span>.</td>\n            <td>Une <span class=\"kw-bio\">leucocyturie</span> modérée n'exclut pas une <span class=\"kw-def\">appendicite pelvienne</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">β-hCG</span></td>\n            <td><strong>Systématique</strong> chez toute <span class=\"kw-clinique\">femme en âge de procréer</span> avec <span class=\"kw-clinique\">douleur abdominale</span> : écarte une <span class=\"kw-etio\">grossesse extra-utérine</span>.</td>\n            <td>N'apporte rien sur l'<span class=\"kw-def\">appendice</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À ne pas demander :</strong> le dosage de la <span class=\"kw-bio\">procalcitonine</span> n'est <strong>pas recommandé</strong> — il n'améliore pas la précision du diagnostic d'<span class=\"kw-clinique\">appendicite</span>.</div>","frequence":0},{"id":"356-16","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens d’imagerie à demander et leurs limites","contenu":"<p>L'imagerie confirme le diagnostic, recherche une complication et élimine <span class=\"kw-clinique\">les</span> diagnostics différentiels. L'<span class=\"kw-imagerie\">échographie</span> est l'examen de 1ʳᵉ intention, la <span class=\"kw-imagerie\">TDM</span> le plus performant.</p>\n\n      <h5><span class=\"kw-imagerie\">Échographie</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-imagerie\">TDM</span> abdomino-pelvienne</h5>\n      <table >\n        <thead>\n          <tr><th>Item</th><th><span class=\"kw-imagerie\">Échographie abdominale</span></th><th><span class=\"kw-imagerie\">TDM</span>-AP injectée (temps portal)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Indication</td>\n            <td>Examen de <strong>1ʳᵉ intention</strong></td>\n            <td><strong>Complication</strong>, <strong>doute diagnostique</strong>, <span class=\"kw-clinique\">sujet âgé</span> ou <span class=\"kw-clinique\">obèse</span></td>\n          </tr>\n          <tr>\n            <td>Performance</td>\n            <td><span class=\"kw-bio\">Sensibilité ≈ 80 %</span></td>\n            <td><span class=\"kw-bio\">Se et Sp &gt; 90-95 %</span> — meilleur examen</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Critères diagnostiques</span></td>\n            <td><span class=\"kw-clinique\">Diamètre</span> <span class=\"kw-chiffre\">≥ 6 mm</span> ; paroi <span class=\"kw-chiffre\">&gt; 3 mm</span> ; appendice <span class=\"kw-imagerie\">incompressible</span> et douloureux au passage de la sonde ; <span class=\"kw-imagerie\">aspect en cocarde</span> ; <span class=\"kw-imagerie\">perte de la différenciation des couches pariétales</span> ; <span class=\"kw-ttt\">infiltration</span> hyperéchogène de la graisse ; stercolithe avec cône d'ombre</td>\n            <td><span class=\"kw-clinique\">Diamètre</span> <span class=\"kw-chiffre\">≥ 8 mm</span> ; épaississement pariétal ; <span class=\"kw-ttt\">infiltration</span> systématique de la graisse péri-appendiculaire ; stercolithe éventuel</td>\n          </tr>\n          <tr>\n            <td>Limites</td>\n            <td>Opérateur-dépendante ; mise en défaut chez l'obèse et si appendice rétro-caecal</td>\n            <td>Irradiante ; produit de contraste iodé</td>\n          </tr>\n          <tr>\n            <td>Délai</td>\n            <td>Disponible et rapide</td>\n            <td><span class=\"kw-chiffre\">&lt; 24 h</span> sans gravité ; <span class=\"kw-chiffre\">&lt; 4 h</span> si <span class=\"kw-alerte\">signes de gravité</span> ou <span class=\"kw-def\">terrain</span> fragile</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Quand demander l'imagerie — stratégie HAS 2012</h5>\n      <table >\n        <thead>\n          <tr><th>Probabilité</th><th>Critères</th><th>Conduite</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Faible</td>\n            <td>Absence de la triade : pas de <span class=\"kw-clinique\">défense en FID</span>, pas d'<span class=\"kw-bio\">hyperleucocytose</span>, <span class=\"kw-bio\">CRP &lt; 8 mg/L</span></td>\n            <td>Diagnostic écarté ; <span class=\"kw-def\">surveillance</span>, pas d'imagerie systématique</td>\n          </tr>\n          <tr>\n            <td>Intermédiaire</td>\n            <td>Un ou deux éléments de la triade seulement</td>\n            <td><span class=\"kw-imagerie\">Imagerie morphologique</span> au minimum (écho ou <span class=\"kw-imagerie\">TDM</span>) ; <span class=\"kw-alerte\">hospitalisation</span> prolongée avant décision</td>\n          </tr>\n          <tr>\n            <td>Forte</td>\n            <td>Triade complète : <span class=\"kw-clinique\">défense en FID</span> + <span class=\"kw-bio\">hyperleucocytose &gt; 10 G/L</span> + <span class=\"kw-bio\">CRP &gt; 8 mg/L</span></td>\n            <td><strong>Homme jeune :</strong> appendicectomie d'emblée ; <strong>femme jeune ou sujet âgé / obèse :</strong> imagerie d'abord pour écarter <span class=\"kw-clinique\">les</span> différentiels</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Complications visibles à l'imagerie</h5>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Complications recherchées</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">Échographie</span></td>\n            <td><span class=\"kw-alerte\">Épanchement liquidien</span> ; <span class=\"kw-alerte\">abcès</span> (ainsi que <span class=\"kw-alerte\">nécrose</span> et <span class=\"kw-clinique\">plastron</span> selon le collège de pédiatrie).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">TDM-AP injectée</span></td>\n            <td><span class=\"kw-alerte\">Abcès</span> ; <span class=\"kw-alerte\">épanchement péri-hépatique</span> ; <span class=\"kw-alerte\">épanchement du cul-de-sac de Douglas</span> ; <span class=\"kw-alerte\">épanchement de la cavité péritonéale</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Autres examens d'imagerie</h5>\n      <ul>\n        <li><strong><span class=\"kw-imagerie\">IRM</span> abdominale :</strong> peu disponible en <span class=\"kw-alerte\">urgence</span> ; <span class=\"kw-imagerie\">préférée à la TDM chez la femme enceinte</span>. Risque <strong>théorique</strong> d'<span class=\"kw-alerte\">hypoacousie fœtale</span> ; <span class=\"kw-alerte\">atteinte thyroïdienne fœtale</span> si injection de <span class=\"kw-ttt\">produit de contraste iodé</span>.</li>\n        <li><strong>Cœlioscopie exploratrice :</strong> proposée chez la <span class=\"kw-clinique\">femme jeune</span> si imagerie non contributive, après <strong>avis gynécologique</strong>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>À ne plus demander :</strong> l'<span class=\"kw-imagerie\">ASP</span> n'a plus aucune place dans le bilan diagnostique de l'<span class=\"kw-clinique\">appendicite</span>.</div>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/acute-appendicitis-2?lang=us","label":"Radiopaedia : Acute appendicitis 2"}]},{"id":"356-17","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge thérapeutique de l’appendicite aiguë non compliquée","contenu":"<p>L'<span class=\"kw-clinique\">appendicite</span> aiguë non compliquée (≈ <span class=\"kw-chiffre\">80 %</span> des cas) relève d'un traitement <strong>chirurgical en <span class=\"kw-alerte\">urgence</span></strong> : l'<span class=\"kw-def\">appendicectomie</span>.</p>\n\n      <h5>Voie d'abord</h5>\n      <ul>\n        <li><span class=\"kw-def\">Cœlioscopie</span> : permet une <strong>exploration complète de l'abdomen</strong>, avec un bénéfice esthétique (cicatrices réduites).</li>\n        <li><span class=\"kw-def\">Courte laparotomie oblique en FID</span> : <span class=\"kw-clinique\">incision de McBurney</span>.</li>\n      </ul>\n\n      <h5>Déroulement de l'intervention</h5>\n      <ol>\n        <li><strong>Exploration de la cavité péritonéale</strong> pour confirmer le diagnostic ou rechercher une autre étiologie ; <span class=\"kw-bio\">prélèvement bactériologique</span> systématique de tout épanchement.</li>\n        <li><span class=\"kw-def\">Appendicectomie</span>.</li>\n        <li><span class=\"kw-bio\">Examen anatomopathologique systématique</span> de la pièce : confirme le diagnostic et élimine une <span class=\"kw-etio\">tumeur de l'appendice</span> (<span class=\"kw-etio\">carcinoïde</span>, <span class=\"kw-etio\">adénocarcinome</span>, <span class=\"kw-etio\">cystadénocarcinome</span>).</li>\n        <li><span class=\"kw-ttt\">Antibioprophylaxie peropératoire de courte durée</span> (<span class=\"kw-chiffre\">24-48 h</span>) par <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span>.</li>\n      </ol>\n\n      <h5>Pré-opératoire et suites</h5>\n      <ul>\n        <li><strong>Pré-opératoire :</strong> patient à jeun ; <span class=\"kw-ttt\">antibiothérapie probabiliste</span> ; <span class=\"kw-ttt\">antalgique</span> ; <span class=\"kw-ttt\">hydratation IV</span>.</li>\n        <li><strong>Reprise alimentaire :</strong> le lendemain de l'intervention.</li>\n        <li><strong>Sortie :</strong> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">24 à 48 h</span> pour les formes non compliquées.</li>\n      </ul>\n\n      <h5>Complications post-opératoires de l'appendicectomie</h5>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Complications</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Infectieuses</strong></td><td><span class=\"kw-alerte\">Infection du site opératoire</span> ; <span class=\"kw-alerte\">abcès de paroi</span> ; <span class=\"kw-alerte\">abcès du cul-de-sac de Douglas</span> ou <span class=\"kw-alerte\">péritonite post-opératoire</span> par lâchage du <strong>moignon appendiculaire</strong>.</td></tr>\n          <tr><td><strong>Hémorragiques</strong></td><td><span class=\"kw-alerte\">Hémorragie</span> ; <span class=\"kw-alerte\">hématome de paroi</span>.</td></tr>\n          <tr><td><strong>Digestives</strong></td><td><span class=\"kw-alerte\">Récidive d'appendicite</span> si moignon appendiculaire trop long (appendicectomie incomplète) ; <span class=\"kw-alerte\">occlusion du grêle</span> — précoce par <span class=\"kw-clinique\">iléus réflexe</span>, tardive sur <span class=\"kw-alerte\">brides</span> ou <span class=\"kw-alerte\">éventration</span> (incision de McBurney, orifice de trocart).</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>Alternative en cours d'évaluation :</strong> le <strong>traitement médical seul</strong> (<span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> ou C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> + imidazolé ; <span class=\"kw-ttt\">fluoroquinolone + imidazolé</span> si <span class=\"kw-ci\">allergie</span> aux β-lactamines) <strong>ne fait pas partie des recommandations</strong> : il reste en cours d'évaluation. La toilette ou le <span class=\"kw-ttt\">drainage</span> péritonéal ne sont pas recommandés dans <span class=\"kw-clinique\">les</span> formes non compliquées.</div>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> le traitement de l'<span class=\"kw-clinique\">appendicite</span> est <em>toujours</em> <span class=\"kw-ttt\">chirurgical</span> et réalisé <span class=\"kw-alerte\">en urgence</span>, en raison du <span class=\"kw-alerte\">risque d'évolution vers une forme compliquée</span> (<span class=\"kw-clinique\">abcès</span>, plastron, <span class=\"kw-clinique\">péritonite</span>).</p><p><strong>Forme non compliquée <span class=\"q\">— sans <span class=\"kw-alerte\">signe de gravité</span></span></strong></p><p><span class=\"kw-imagerie\">imagerie</span> (<span class=\"kw-imagerie\">échographie</span> / <span class=\"kw-imagerie\">TDM</span>) réalisée en <span class=\"kw-chiffre\">&lt; 24 h</span></p><ul><li><span class=\"kw-ttt\">Appendicectomie</span> dans un délai <span class=\"kw-chiffre\">&lt; 24 h</span></li></ul><p><strong><span class=\"kw-alerte\">Signes de gravité</span> ou <span class=\"kw-def\">terrain</span> fragile <span class=\"q\">— enfant, sujet âgé</span></strong></p><p><span class=\"kw-imagerie\">imagerie</span> réalisée en <span class=\"kw-chiffre\">&lt; 4 h</span></p><ul><li><span class=\"kw-ttt\">Appendicectomie</span> dans un délai <span class=\"kw-chiffre\">&lt; 4 h</span></li></ul><p><strong><span class=\"kw-clinique\">Péritonite</span> appendiculaire généralisée <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> chirurgicale absolue</span></strong></p><p>aucun examen d'imagerie supplémentaire si tableau typique → bloc immédiat</p><ul><li><span class=\"kw-alerte\">Défense généralisée voire contracture</span> + <span class=\"kw-clinique\">fièvre &gt; 38,5 °C</span></li></ul>","hospit":"<p><strong>Tableau typique</strong></p><ul><li><span class=\"kw-ttt\">Intervention</span> programmée au plus vite après <span class=\"kw-ttt\">consultation d'anesthésie</span> en <span class=\"kw-alerte\">urgence</span></li></ul><p><strong>Tableau incomplet / diagnostic douteux</strong></p><ul><li><span class=\"kw-imagerie\">TDM</span> + <span class=\"kw-clinique\">hospitalisation pour surveillance</span> (durée allongée avant décision)</li></ul><p><strong>Absence de la tétrade <span class=\"q\">— pas de défense, ni hyperleucocytose, ni <span class=\"kw-clinique\">fièvre</span>, ni <span class=\"kw-bio\">CRP</span></span></strong></p><ul><li>Diagnostic <span class=\"kw-alerte\">écarté</span></li></ul><p><strong>Nourrisson / jeune enfant</strong></p><ul><li><span class=\"kw-clinique\">Observation</span> de quelques jours possible avant la décision opératoire</li></ul>","redflags":"<ul><li><span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\">3 complications</span> : <span class=\"kw-alerte\">abcès</span>, <span class=\"kw-alerte\">plastron</span>, <span class=\"kw-alerte\">péritonite</span> appendiculaire</li><li><span class=\"kw-clinique\">Péritonite</span> : <span class=\"kw-alerte\">faciès gris / terreux</span>, <span class=\"kw-alerte\">défense généralisée voire contracture</span>, <span class=\"kw-clinique\">fièvre &gt; 38,5 °C</span>, <span class=\"kw-clinique\">occlusion fébrile</span></li><li><span class=\"kw-clinique\">Abcès</span> : <span class=\"kw-clinique\">AEG</span> + <span class=\"kw-clinique\">fièvre &gt; 38,5 °C en plateau</span> + <span class=\"kw-clinique\">syndrome subocclusif</span> (<span class=\"kw-clinique\">iléus</span> réflexe)</li><li>Terrains à <span class=\"kw-alerte\">risque de perforation</span> : <span class=\"kw-etio\">enfant</span> (<span class=\"kw-chiffre\">70-80 %</span>), <span class=\"kw-etio\">sujet âgé</span> (<span class=\"kw-chiffre\">30 %</span>)</li><li>Nourrisson : <span class=\"kw-clinique\">évolution</span> <span class=\"kw-alerte\">rapide vers perforation et péritonite</span> ; <span class=\"kw-clinique\">appendicite</span> <span class=\"kw-alerte\">toujours compliquée avant 6 ans</span>, <span class=\"kw-alerte\">pronostic vital avant 1 an</span></li><li>Sujet âgé : éliminer impérativement une <span class=\"kw-etio\">tumeur colique droite</span></li><li><span class=\"kw-alerte\">Appendicite « toxique »</span> (rare) : translocation <span class=\"kw-etio\">bactérienne</span>, <span class=\"kw-clinique\">évolution</span> possible vers le décès</li></ul>","principes":"<p><strong>Règle d'or :</strong> <span class=\"kw-ttt\">appendicectomie</span> chirurgicale en <span class=\"kw-alerte\">urgence</span> ; <span class=\"kw-ttt\">examen anatomopathologique</span> systématique de la pièce (élimine une tumeur). Le <span class=\"kw-ttt\">traitement médical seul</span> n'est <span class=\"kw-ci\">pas recommandé</span> (en cours d'évaluation).</p><p><strong>Préparation pré-opératoire</strong></p><ul><li>Patient <span class=\"kw-ttt\">à jeun</span></li><li><span class=\"kw-ttt\">Antibiothérapie probabiliste</span></li><li><span class=\"kw-ttt\">Antalgique</span> (<span class=\"kw-ttt\">paracétamol</span> ou phloroglucinol) + <span class=\"kw-ttt\">hydratation IV</span> + correction des troubles hydro-électrolytiques</li></ul><p><strong>Geste : appendicectomie</strong></p><ul><li>Voie d'abord : <span class=\"kw-ttt\">incision de McBurney</span> (laparotomie oblique en FID) ou <span class=\"kw-ttt\">cœlioscopie</span></li><li>Exploration de la cavité péritonéale (prélèvement bactériologique si épanchement)</li><li><span class=\"kw-ttt\">Antibioprophylaxie peropératoire</span> courte (<span class=\"kw-chiffre\">24-48 h</span>) par <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span></li><li>Pas de toilette ni de <span class=\"kw-ttt\">drainage</span> péritonéal si forme <span class=\"kw-clinique\">non compliquée</span></li></ul><p><strong><span class=\"kw-clinique\">Péritonite</span> appendiculaire</strong></p><p><span class=\"kw-ttt\">antibiothérapie</span> probabiliste puis adaptée pendant <span class=\"kw-chiffre\">5-7 jours</span></p><ul><li><span class=\"kw-ttt\">Toilette péritonéale</span> + <span class=\"kw-ttt\">drainage</span> + <span class=\"kw-ttt\">appendicectomie</span> en <span class=\"kw-alerte\">urgence</span> (cœlio ou laparotomie)</li></ul><p><strong><span class=\"kw-clinique\">Abcès</span> appendiculaire</strong></p><p><span class=\"kw-ttt\">ATB</span> <span class=\"kw-chiffre\">7 jours</span> + <span class=\"kw-ttt\">appendicectomie à 3 mois</span></p><ul><li><span class=\"kw-ttt\">Drainage percutané radiologique</span> (grande taille) ou <span class=\"kw-ttt\">chirurgical</span> (petite taille / signes péritonéaux)</li></ul><p><strong>Plastron appendiculaire</strong></p><p><span class=\"kw-ttt\">ATB</span> <span class=\"kw-chiffre\">7 jours</span> + <span class=\"kw-ttt\">appendicectomie à 3 mois</span></p><ul><li>Pas de geste de <span class=\"kw-ttt\">drainage</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-etio\">dissection</span> dangereuse, risque de plaie / <span class=\"kw-clinique\">fistule</span> du grêle)</li></ul>","suivi":"<p><strong>Anapath :</strong> <span class=\"kw-ttt\">examen anatomopathologique</span> systématique de la pièce — élimine une tumeur (carcinoïde &gt; adénocarcinome &gt; cystadénocarcinome).<br><strong>Suites simples :</strong> reprise de l'<span class=\"kw-clinique\">alimentation le lendemain</span> ; sortie en <span class=\"kw-chiffre\">24-48 h</span> pour <span class=\"kw-clinique\">les</span> formes non compliquées.<br><strong><span class=\"kw-def\">Pronostic</span> :</strong> <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">&lt; 0,5 %</span> (<span class=\"kw-chiffre\">0,1 %</span> non compliquées · <span class=\"kw-chiffre\">1,5 %</span> perforations) ; <span class=\"kw-def\">morbidité</span> globale <span class=\"kw-chiffre\">10 %</span>.<br><strong>Complications post-op :</strong> <span class=\"kw-alerte\">infection du site opératoire</span>, <span class=\"kw-alerte\">abcès du Douglas / péritonite</span> (lâchage du moignon), <span class=\"kw-alerte\">hémorragie</span> / hématome de paroi, <span class=\"kw-alerte\">occlusion du grêle</span> (<span class=\"kw-clinique\">iléus</span> réflexe précoce ; brides / éventration tardives), récidive si moignon trop long.<br><strong>Différé :</strong> appendicectomie programmée à <span class=\"kw-chiffre\">3 mois</span> après un <span class=\"kw-clinique\">abcès</span> ou un plastron.</p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/acute-appendicitis-2?lang=us","label":"Radiopaedia : Acute appendicitis 2"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Douleur de la FID évocatrice d'appendicite — Triade HAS 2012 : défense en FID · hyperleucocytose > 10 G/L · CRP > 8 mg/L","detail":"<h4>CAT — suspicion d'<span class=\"kw-clinique\">appendicite</span> aiguë — Stratification HAS 2012 (probabilité clinico-<span class=\"kw-ttt\">biologique</span>) puis <span class=\"kw-def\">terrain</span></h4>","branches":[{"to":"t-ecarte","label":"Peu probable : aucun des 3 critères (pas de défense, pas d'hyperleucocytose, CRP < 8)","color":"green"},{"to":"t-intermediaire","label":"Probabilité intermédiaire : ni peu probable, ni très probable","color":"amber"},{"to":"q-terrain","label":"Très probable : défense FID + hyperleucocytose > 10 G/L + CRP > 8","color":"red"}]},{"id":"t-ecarte","kind":"terminal","label":"Appendicite écartée → surveillance","color":"green","detail":"<h4>Critères</h4><ul><li>Absence concomitante de <span class=\"kw-clinique\">défense en FID</span></li><li>Absence d'<span class=\"kw-bio\">hyperleucocytose</span></li><li><span class=\"kw-bio\">CRP</span> <span class=\"kw-chiffre\">&lt; 8 mg/L</span></li></ul><h4>CAT</h4><ul><li>Pas de <span class=\"kw-ttt\">chirurgie</span> ni d'imagerie systématique</li><li><span class=\"kw-clinique\">Surveillance</span> ; rechercher un <span class=\"kw-etio\">diagnostic différentiel</span> (<span class=\"kw-bio\">BU</span>, <span class=\"kw-bio\">β-HCG</span> chez la femme en âge de procréer)</li></ul>"},{"id":"t-intermediaire","kind":"terminal","label":"Imagerie + hospitalisation pour surveillance","color":"amber","detail":"<h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie abdominale</span> en 1re intention, ou <span class=\"kw-imagerie\">TDM</span> — examen morphologique au minimum</li></ul><h4>CAT</h4><ul><li><span class=\"kw-clinique\">Hospitalisation</span> avec durée de <span class=\"kw-def\">surveillance</span> allongée avant la décision thérapeutique</li></ul>"},{"id":"q-terrain","kind":"decision","label":"Terrain à risque diagnostique ? — Femme en âge de procréer · sujet âgé · obèse","branches":[{"to":"t-chir-emblee","label":"Non — homme jeune, tableau typique","color":"red"},{"to":"t-imagerie-chir","label":"Oui — femme en âge de procréer / sujet âgé / obèse","color":"amber"}]},{"id":"t-chir-emblee","kind":"terminal","label":"Appendicectomie d'emblée","color":"red","detail":"<h4>CAT</h4><ul><li><span class=\"kw-ttt\">Intervention</span> programmée au plus vite après <span class=\"kw-ttt\">consultation d'anesthésie</span> en <span class=\"kw-alerte\">urgence</span> (aucune imagerie indispensable)</li></ul><h4>Pré-opératoire</h4><ul><li>Patient <span class=\"kw-ttt\">à jeun</span>, <span class=\"kw-ttt\">ATB probabiliste</span>, <span class=\"kw-ttt\">antalgique</span> + <span class=\"kw-ttt\">hydratation IV</span></li><li>Délai <span class=\"kw-chiffre\">&lt; 24 h</span> (ou <span class=\"kw-chiffre\">&lt; 4 h</span> si <span class=\"kw-alerte\">signe de gravité</span> / <span class=\"kw-def\">terrain</span> fragile)</li></ul><h4>Geste</h4><ul><li><span class=\"kw-ttt\">Appendicectomie</span> (McBurney ou cœlioscopie) + <span class=\"kw-ttt\">examen anatomopathologique</span> systématique</li></ul>"},{"id":"t-imagerie-chir","kind":"terminal","label":"Imagerie d'abord puis chirurgie","color":"amber","detail":"<h4>Femme en âge de procréer</h4><ul><li><span class=\"kw-bio\">β-HCG</span> + <span class=\"kw-imagerie\">échographie</span> + examen gynécologique pour écarter une <span class=\"kw-etio\">GEU</span>, une <span class=\"kw-etio\">salpingite</span>, une <span class=\"kw-etio\">torsion d'annexe</span> ; cœlioscopie si imagerie non contributive après avis gynéco</li></ul><h4>Sujet âgé</h4><ul><li><span class=\"kw-imagerie\">TDM</span> systématique : éliminer une <span class=\"kw-etio\">tumeur colique droite</span></li></ul><h4>Obèse</h4><ul><li><span class=\"kw-imagerie\">TDM</span> (<span class=\"kw-imagerie\">échographie</span> peu performante)</li></ul><h4>Puis</h4><ul><li><span class=\"kw-ttt\">Appendicectomie</span> selon <span class=\"kw-clinique\">les</span> résultats de l'imagerie</li></ul>"}]},"cards":[{"i":"102998d35556","n":356,"o":"356-1","u":"Diagnostic positif","t":"Connaître la symptomatologie de l’appendicite chez l’enfant et ses différentes formes cliniques","q":"Comment se présente une appendicite chez le grand enfant, par rapport à l'adulte ?","a":"<p>Chez le grand enfant, la symptomatologie de l'appendicite est <strong>superposable à celle de l'adulte</strong>. Elle se caractérise par une <strong>douleur de la fosse iliaque droite</strong>, une fièvre modérée, et une <strong>défense au point de McBurney</strong>.</p>"},{"i":"48bc2f5591e7","n":356,"o":"356-1","u":"Diagnostic positif","t":"Connaître la symptomatologie de l’appendicite chez l’enfant et ses différentes formes cliniques","q":"Comment une appendicite à localisation rétro-caecale peut-elle modifier la présentation clinique ?","a":"<p>Une appendicite à localisation rétro-caecale se manifeste par un <strong>psoïtis franc</strong>, une <strong>douleur du flanc droit</strong>. L'examen peut révéler une douleur au palper bimanuel en décubitus latéral gauche.</p>"},{"i":"84e76cf5fe7c","n":356,"o":"356-1","u":"Diagnostic positif","t":"Connaître la symptomatologie de l’appendicite chez l’enfant et ses différentes formes cliniques","q":"Quelle est la présentation clinique d'une appendicite sous-hépatique ?","a":"<p>L'appendicite sous-hépatique présente un tableau clinique qui simule une <strong>pseudo-cholécystite</strong>, avec une douleur et une défense de l'<strong>hypochondre droit</strong>.</p>"},{"i":"8bd7ab9f9983","n":356,"o":"356-1","u":"Diagnostic positif","t":"Connaître la symptomatologie de l’appendicite chez l’enfant et ses différentes formes cliniques","q":"Quels sont les signes cliniques distinctifs d'une appendicite à localisation pelvienne ?","a":"<p>Une appendicite à localisation pelvienne se caractérise principalement par une <strong>douleur hypogastrique</strong>, associée à des <strong>signes urinaires</strong> comme la pollakiurie et la dysurie, ainsi que des <strong>ténesmes</strong> et de <strong>faux besoins</strong>.</p>"},{"i":"98616b5a2c7a","n":356,"o":"356-1","u":"Diagnostic positif","t":"Connaître la symptomatologie de l’appendicite chez l’enfant et ses différentes formes cliniques","q":"Comment se manifeste l'appendicite chez le nourrisson et quels sont les risques associés ?","a":"<p>Chez le nourrisson, la symptomatologie de l'appendicite est <strong>non spécifique et trompeuse</strong>, incluant un syndrome d'altération de l'état général (AEG), de la fièvre, des vomissements, une diarrhée, une distension abdominale, une déshydratation, ainsi qu'une agitation et de l'insomnie. L'évolution est rapidement progressive vers la <strong>perforation</strong>, engageant le pronostic vital avant 1 an.</p>"},{"i":"b3f6a66d52e0","n":356,"o":"356-1","u":"Diagnostic positif","t":"Connaître la symptomatologie de l’appendicite chez l’enfant et ses différentes formes cliniques","q":"Quelles sont les particularités cliniques de l'appendicite chez le jeune enfant, et quels sont les pièges diagnostiques ?","a":"<p>Chez le jeune enfant, le diagnostic est difficile, surtout s'il ne se laisse pas examiner. La douleur est de <strong>localisation peu précise</strong>, la fièvre est modérée, et il y a présence de nausées et vomissements. Les pièges diagnostiques classiques qui retardent le diagnostic sont la <strong>gastro-entérite aiguë</strong> et l'<strong>adénolymphite mésentérique</strong>.</p>"},{"i":"0d44e3d88bc5","n":356,"o":"356-10","u":"Diagnostic positif","t":"Connaître les signes cliniques et biologiques en défaveur d’une appendicite aiguë","q":"Quel score est parfois utilisé comme aide à l'orientation diagnostique pour une appendicite aiguë, bien qu'il ne soit pas validé pour la pratique courante ?","a":"<p>Il s'agit du score d'<strong>Alvarado</strong>, qui ne doit être utilisé que comme une aide à l'orientation.</p>"},{"i":"3d6c2d39b027","n":356,"o":"356-10","u":"Diagnostic positif","t":"Connaître les signes cliniques et biologiques en défaveur d’une appendicite aiguë","q":"Selon les recommandations de la HAS 2012, quels sont les signes négatifs qui permettent d'écarter le diagnostic d'appendicite aiguë en cas d'absence concomitante ?","a":"<p>Le diagnostic d'appendicite aiguë peut être écarté en l'absence concomitante de :</p><ul><li><strong>Fièvre</strong></li><li><strong>Défense en fosse iliaque droite (FID)</strong></li><li><strong>Hyperleucocytose</strong></li><li>Élévation de la <strong>CRP &lt; 8 mg/L</strong></li></ul>"},{"i":"8d5a07e5bef6","n":356,"o":"356-10","u":"Diagnostic positif","t":"Connaître les signes cliniques et biologiques en défaveur d’une appendicite aiguë","q":"Dans le score d'Alvarado pour l'appendicite aiguë, une défense en fosse iliaque droite (FID) rapporte combien de points ?","a":"<p>Une défense en fosse iliaque droite (FID) rapporte <strong>2 points</strong> dans le score d'Alvarado.</p>"},{"i":"ad43351928ba","n":356,"o":"356-10","u":"Diagnostic positif","t":"Connaître les signes cliniques et biologiques en défaveur d’une appendicite aiguë","q":"Selon le score d'Alvarado, à partir de quel intervalle de score l'appendicite est-elle considérée comme « improbable » ?","a":"<p>Une appendicite est considérée comme <strong>improbable</strong> pour un score d'Alvarado de <strong>0 à 4</strong>.</p>"},{"i":"9f576a6c85d0","n":356,"o":"356-14","u":"Diagnostic positif","t":"Connaître les signes cliniques des trois principales complications de l’appendicite : abcès, plastron, péritonite.","q":"Quels sont les signes cliniques distinctifs d'un <strong>plastron appendiculaire</strong> compliqué d'une appendicite, à l'examen physique et biologique ?","a":"<p>Cliniquement, le plastron appendiculaire se manifeste par :</p><ul><li>Une <strong>fièvre modérée</strong>.</li><li>Une douleur et une <strong>masse douloureuse et empâtement</strong> en fosse iliaque droite (FID), avec une peau locale pouvant être rouge et chaude, le reste de l'abdomen restant souple.</li><li>Biologiquement, une <strong>hyperleucocytose à PNN</strong> est présente.</li></ul>"},{"i":"a2be3bfb6312","n":356,"o":"356-14","u":"Diagnostic positif","t":"Connaître les signes cliniques des trois principales complications de l’appendicite : abcès, plastron, péritonite.","q":"Comment différencier cliniquement entre un <strong>abcès appendiculaire</strong> et un plastron appendiculaire ?","a":"<p>L'abcès appendiculaire se distingue du plastron par :</p><ul><li>Des <strong>signes généraux plus marqués</strong>, notamment une altération de l'état général (AEG) et une <strong>fièvre > 38,5 °C en plateau</strong>, sans frissons.</li><li>Une douleur et une <strong>défense en FID</strong> plus intenses, avec un empâtement ou une masse pouvant s'étendre au flanc droit.</li><li>La présence possible d'un <strong>syndrome subocclusif</strong> par iléus réflexe.</li><li>Biologiquement, une <strong>hyperleucocytose marquée (> 15 000/mm³)</strong>.</li></ul>"},{"i":"ed09a9aac326","n":356,"o":"356-14","u":"Diagnostic positif","t":"Connaître les signes cliniques des trois principales complications de l’appendicite : abcès, plastron, péritonite.","q":"Quels sont les signes cliniques et généraux d'une <strong>péritonite appendiculaire généralisée</strong> ?","a":"<p>Clairement définie comme une urgence chirurgicale absolue, la péritonite appendiculaire généralisée se caractérise par :</p><ul><li>Une <strong>altération de l'état général</strong>, avec un faciès gris, terreux.</li><li>Une <strong>douleur intense et généralisée</strong>, associée à une <strong>défense généralisée voire une contracture</strong>.</li><li>Une <strong>fièvre > 38,5 °C</strong>.</li><li>Un <strong>toucher rectal douloureux</strong> au cul-de-sac de Douglas.</li><li>Un signe négatif clé est l'<strong>absence de pneumopéritoine</strong>, avec une matité pré-hépatique conservée.</li></ul>"},{"i":"12c65e356569","n":356,"o":"356-15","u":"Examens complémentaires","t":"Connaître les examens biologiques à demander et leurs limites","q":"Quels sont les résultats attendus et les limites de la Numération Formule Sanguine (NFS) dans le diagnostic de l'appendicite aiguë ?","a":"<p>Dans l'appendicite aiguë, la NFS révèle une <strong>hyperleucocytose à polynucléaires neutrophiles (PNN &gt; 10 000/mm³)</strong> dans plus de 80 % des cas. C'est le marqueur le plus souvent perturbé.</p><ul><li><strong>Limites :</strong> Elle peut être normale dans les formes débutantes et n'est pas spécifique du diagnostic d'appendicite.</li></ul>"},{"i":"45c9ce430116","n":356,"o":"356-15","u":"Examens complémentaires","t":"Connaître les examens biologiques à demander et leurs limites","q":"Le dosage de la procalcitonine est-il recommandé dans la suspicion d'appendicite aiguë selon les référentiels de l'EDN ?","a":"<p>Non, le dosage de la <strong>procalcitonine</strong> n'est <strong>pas recommandé</strong> dans le bilan diagnostique de l'appendicite aiguë, car il n'améliore pas la précision du diagnostic.</p>"},{"i":"6b47981c20e7","n":356,"o":"356-15","u":"Examens complémentaires","t":"Connaître les examens biologiques à demander et leurs limites","q":"Quels sont l'intérêt et les limites de la CRP et de la bandelette urinaire dans le bilan d'une appendicite aiguë ?","a":"<ul><li>La <strong>CRP</strong> est élevée si l'inflammation évolue depuis quelques heures, mais est normale dans <strong>50% des cas</strong> d'appendicite catarrhale débutante.</li><li>La <strong>bandelette urinaire</strong> est utile pour <strong>éliminer une infection urinaire</strong>, mais une <strong>leucocyturie modérée</strong> n'exclut pas une appendicite pelvienne.</li></ul>"},{"i":"84c13edd47c2","n":356,"o":"356-15","u":"Examens complémentaires","t":"Connaître les examens biologiques à demander et leurs limites","q":"Quel est l'intérêt du dosage des β-hCG chez la femme en âge de procréer lors d'une suspicion d'appendicite aiguë ?","a":"<p>Le dosage des <strong>β-hCG</strong> est systématique chez toute femme en âge de procréer présentant une douleur abdominale. Il permet d'<strong>écarter une grossesse extra-utérine</strong> (GEU), mais n'apporte aucune information sur l'appendice lui-même.</p>"},{"i":"d81bb399f744","n":356,"o":"356-15","u":"Examens complémentaires","t":"Connaître les examens biologiques à demander et leurs limites","q":"Quel est l'intérêt général du bilan biologique dans le diagnostic de l'appendicite aiguë selon le contexte de l'EDN ?","a":"<p>En contexte d'EDN, le bilan biologique pour l'appendicite aiguë <strong>conforte le diagnostic</strong> et <strong>écarte certains diagnostics différentiels</strong>, mais il ne permet jamais de poser le diagnostic à lui seul. Son apport reste <strong>limité</strong>.</p>"},{"i":"01b85b508ca5","n":356,"o":"356-16","u":"Examens complémentaires","t":"Connaître les examens d’imagerie à demander et leurs limites","q":"Quelles sont les limites principales de l'échographie et de la TDM dans le diagnostic de l'appendicite aiguë, et quel examen est préféré chez la femme enceinte ?","a":"<ul><li>Les limites de l'échographie sont qu'elle est <strong>opérateur-dépendante</strong> et sa mise en défaut chez l'<strong>obèse</strong> ou si l'appendice est <strong>rétro-caecal</strong>.</li><li>Les limites de la TDM sont son caractère <strong>irradiant</strong> et l'utilisation de <strong>produit de contraste iodé</strong>.</li><li>Chez la femme enceinte, l'<strong>IRM abdominale</strong> est préférée, bien que moins disponible en urgence.</li></ul>"},{"i":"1041534109e9","n":356,"o":"356-16","u":"Examens complémentaires","t":"Connaître les examens d’imagerie à demander et leurs limites","q":"Quel est l'examen d'imagerie de première intention pour confirmer une appendicite aiguë et quels sont ses principaux critères diagnostiques échographiques ?","a":"<p>L'examen d'imagerie de première intention est l'<strong>échographie abdominale</strong>.</p><ul><li>Diamètre de l'appendice <strong>supérieur ou égal à 6 mm</strong>.</li><li>Paroi de l'appendice <strong>supérieure à 3 mm</strong>.</li><li>Appendice <strong>incompressible</strong> et <strong>douloureux</strong> au passage de la sonde.</li><li>Aspect en <strong>cocarde</strong>, perte de la différenciation des couches pariétales.</li><li><strong>Infiltration hyperéchogène de la graisse</strong> péri-appendiculaire.</li><li>Présence d'un <strong>stercorite avec cône d'ombre</strong>.</li></ul>"},{"i":"443b9384700d","n":356,"o":"356-16","u":"Examens complémentaires","t":"Connaître les examens d’imagerie à demander et leurs limites","q":"Dans quel contexte la TDM abdomino-pelvienne injectée est-elle indiquée pour l'appendicite aiguë et quels sont ses principaux critères diagnostiques ?","a":"<p>La TDM abdomino-pelvienne injectée est indiquée en cas de <strong>complication</strong>, de <strong>doute diagnostique</strong>, ou chez le <strong>sujet âgé ou obèse</strong>.</p><ul><li>Diamètre de l'appendice <strong>supérieur ou égal à 8 mm</strong>.</li><li><strong>Épaississement pariétal</strong>.</li><li><strong>Infiltration systématique de la graisse péri-appendiculaire</strong>.</li><li>Stécorite éventuel.</li></ul>"},{"i":"5ceac051b954","n":356,"o":"356-16","u":"Examens complémentaires","t":"Connaître les examens d’imagerie à demander et leurs limites","q":"Quelles complications de l'appendicite aiguë peuvent être recherchées spécifiquement par l'échographie et la TDM abdominale ?","a":"<ul><li>L'<strong>échographie</strong> peut rechercher un <strong>épanchement liquidien</strong> et un <strong>abcès</strong> (ainsi que nécrose et plastron selon le collège de pédiatrie).</li><li>La <strong>TDM-AP injectée</strong> peut rechercher un <strong>abcès</strong>, un <strong>épanchement péri-hépatique</strong>, un <strong>épanchement du cul-de-sac de Douglas</strong> et un <strong>épanchement de la cavité péritonéale</strong>.</li></ul>"},{"i":"84796d601b04","n":356,"o":"356-16","u":"Examens complémentaires","t":"Connaître les examens d’imagerie à demander et leurs limites","q":"Comment l'imagerie s'intègre-t-elle dans la stratégie diagnostique de l'appendicite aiguë selon la probabilité clinique (stratégie HAS 2012) chez un patient avec une probabilité intermédiaire ?","a":"<p>Pour une probabilité intermédiaire, caractérisée par la présence d'<strong>un ou deux éléments de la triade</strong> (défense en FID, hyperleucocytose > 10 G/L, CRP > 8 mg/L), une <strong>imagerie morphologique au minimum (échographie ou TDM)</strong> est recommandée, avec une hospitalisation prolongée avant décision.</p>"},{"i":"b64fa56c4448","n":356,"o":"356-17","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique de l’appendicite aiguë non compliquée","q":"Quelles sont les complications post-opératoires possibles de l'appendicectomie ?","a":"<ul><li><strong>Complications infectieuses</strong> : infection du site opératoire, abcès de paroi, abcès du cul-de-sac de Douglas, ou péritonite post-opératoire par lâchage du moignon appendiculaire.</li><li><strong>Complications hémorragiques</strong> : hémorragie, hématome de paroi.</li><li><strong>Complications digestives</strong> : récidive d'appendicite si moignon appendiculaire trop long (appendicectomie incomplète), occlusion du grêle (précoce par iléus réflexe, ou tardive sur brides ou éventration).</li></ul>"},{"i":"c97a80d17fae","n":356,"o":"356-17","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique de l’appendicite aiguë non compliquée","q":"Quel est le traitement de première intention d'une appendicite aiguë non compliquée et quelles sont les voies d'abord chirurgicales ?","a":"<p>Le traitement de première intention est l'<strong>appendicectomie chirurgicale en urgence</strong> (concerne environ 80% des cas d'appendicite).</p><ul><li>La <strong>cœlioscopie</strong> est la voie d'abord privilégiée. Elle permet une exploration complète de l'abdomen et offre un bénéfice esthétique par des cicatrices réduites.</li><li>La <strong>courte laparotomie oblique en fosse iliaque droite (FID)</strong> par incision de McBurney est une alternative.</li></ul>"},{"i":"cd14687831f9","n":356,"o":"356-17","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique de l’appendicite aiguë non compliquée","q":"Quels sont les principes et le déroulement de l'appendicectomie pour une appendicite aiguë non compliquée ?","a":"<ul><li><strong>Exploration de la cavité péritonéale</strong> pour confirmer le diagnostic ou rechercher une autre étiologie.</li><li><strong>Prélèvement bactériologique systématique</strong> de tout épanchement.</li><li><strong>Appendicectomie</strong>.</li><li><strong>Examen anatomopathologique systématique</strong> de la pièce opératoire pour confirmer le diagnostic et éliminer une tumeur de l'appendice (carcinoïde, adénocarcinome, cystadénocarcinome).</li><li><strong>Antibioprophylaxie peropératoire de courte durée</strong> (<strong>24-48h</strong>), généralement par association <strong>amoxicilline-acide clavulanique</strong>.</li></ul>"},{"i":"dd4143974f46","n":356,"o":"356-17","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique de l’appendicite aiguë non compliquée","q":"Quelle est la prise en charge pré-opératoire et les suites habituelles de l'appendicectomie pour une appendicite aiguë non compliquée ?","a":"<ul><li><strong>Pré-opératoire</strong> : patient à jeun, antibiothérapie probabiliste, antalgiques, hydratation intraveineuse.</li><li><strong>Reprise alimentaire</strong> : le lendemain de l'intervention.</li><li><strong>Sortie</strong> : généralement dans les <strong>24 à 48 heures</strong> pour les formes non compliquées.</li><li>Par ailleurs, la toilette ou le drainage péritonéal ne sont <strong>pas recommandés</strong> dans les formes non compliquées.</li></ul>"},{"i":"29621167bac3","n":356,"o":"356-3","u":"Suivi et/ou pronostic","t":"Connaître les complications chez l’enfant","q":"Quelle est la principale complication de l'appendicite aiguë chez l'enfant et à quoi est-elle due ?","a":"<p>La principale complication de l'appendicite aiguë chez l'enfant est la <strong>perforation</strong>, évoluant vers la <strong>péritonite aiguë généralisée</strong>. Elle est favorisée par la <strong>paroi appendiculaire fine</strong> et un <strong>grand omentum court</strong> qui cloisonne mal l'infection.</p>"},{"i":"382916912bf3","n":356,"o":"356-3","u":"Suivi et/ou pronostic","t":"Connaître les complications chez l’enfant","q":"Quel est le principal facteur favorisant la perforation appendiculaire pédiatrique ?","a":"<p>Le principal facteur favorisant la perforation appendiculaire pédiatrique est le <strong>retard diagnostique</strong>.</p>"},{"i":"4d2973cb9095","n":356,"o":"356-3","u":"Suivi et/ou pronostic","t":"Connaître les complications chez l’enfant","q":"Quelle est la fréquence de l'appendicite perforée chez l'enfant par rapport à l'adulte ?","a":"<p>L'indice de perforation est élevé chez l'enfant : <strong>70 à 80 %</strong> des appendicites sont <strong>déjà perforées au diagnostic</strong>, contre environ 30 % chez le sujet âgé.</p>"},{"i":"af2d245b2324","n":356,"o":"356-3","u":"Suivi et/ou pronostic","t":"Connaître les complications chez l’enfant","q":"Quel est l'impact de l'âge sur le risque de complication de l'appendicite chez l'enfant ?","a":"<ul><li><strong>Avant 6 ans</strong>, l'appendicite est presque toujours compliquée au moment de la prise en charge.</li><li><strong>Avant 1 an</strong>, la complication engage le pronostic vital.</li></ul>"},{"i":"107779b2cbfc","n":356,"o":"356-5","u":"Prise en charge","t":"Connaître les principes de prise en charge","q":"Quels sont les délais d'intervention chirurgicale recommandés pour l'appendicite aiguë en fonction de la situation clinique ?","a":"<ul><li>En l'absence de signe de gravité : appendicectomie dans les <strong>moins de 24 heures</strong>.</li><li>En présence de signes de gravité ou sur terrain fragile : appendicectomie dans les <strong>moins de 4 heures</strong>.</li></ul>"},{"i":"3c10d800c326","n":356,"o":"356-5","u":"Prise en charge","t":"Connaître les principes de prise en charge","q":"Quelle a été l'évolution de la doctrine concernant l'indication de l'appendicectomie ?","a":"<p>L'appendicectomie n'est plus systématique devant toute douleur de la fosse iliaque droite. Elle est décidée uniquement après une <strong>démarche diagnostique structurée</strong> incluant clinique, biologie et imagerie.</p>"},{"i":"4d8833bdffe3","n":356,"o":"356-5","u":"Prise en charge","t":"Connaître les principes de prise en charge","q":"Quelles sont les mesures pré-opératoires essentielles à mettre en place face à une appendicite aiguë ?","a":"<ul><li>Le patient doit être <strong>à jeun</strong>.</li><li>Une <strong>antibiothérapie probabiliste</strong> dirigée contre les germes digestifs doit être administrée.</li><li>Des <strong>antalgiques</strong> (paracétamol ou phloroglucinol) sont prescrits.</li><li>Une <strong>hydratation par voie IV</strong> et correction des troubles hydro-électrolytiques sont nécessaires.</li><li>Une <strong>consultation d'anesthésie</strong> en urgence doit être réalisée.</li></ul>"},{"i":"b7ba0cd9192d","n":356,"o":"356-5","u":"Prise en charge","t":"Connaître les principes de prise en charge","q":"Quel est le principe général de prise en charge chirurgicale d'une appendicite aiguë confirmée ?","a":"<p>Le traitement de l'appendicite aiguë confirmée est <strong>toujours chirurgical</strong> en raison du risque d'évolution vers une forme compliquée.</p>"},{"i":"43e0791c1124","n":356,"o":"356-7","u":"Définition","t":"Connaître la définition de l’appendicite aiguë","q":"Quelle est la physiopathologie de l'appendicite aiguë en l'absence de traitement ?","a":"<p>L'obstruction initiale entraîne une <strong>pullulation microbienne</strong> et l'infection de l'appendice. L'inflammation gagne les 4 couches pariétales (appendicite <strong>suppurée</strong>), la distension comprime la vascularisation et entraîne une <strong>ischémie artérielle</strong>. L'évolution se fait ensuite vers la <strong>gangrène</strong> puis la <strong>perforation</strong> si elle n'est pas traitée.</p>"},{"i":"4a4656921cee","n":356,"o":"356-7","u":"Définition","t":"Connaître la définition de l’appendicite aiguë","q":"Quels sont les autres mécanismes pouvant entraîner une obstruction appendiculaire et provoquer une appendicite aiguë ?","a":"<ul><li>Une <strong>infection parasitair</strong>e (ex : ascaris).</li><li>Une <strong>sténose inflammatoire</strong> (ex : maladie de Crohn).</li><li>Une <strong>tumeur</strong> (le plus souvent carcinoïde).</li></ul>"},{"i":"68a14fc18322","n":356,"o":"356-7","u":"Définition","t":"Connaître la définition de l’appendicite aiguë","q":"Quelles sont les causes les plus classiques de l'obstruction de la lumière appendiculaire dans l'appendicite aiguë ?","a":"<ul><li>Le <strong>stercolithe</strong> (concrétion dure de matières fécales).</li><li>L'<strong>hyperplasie lymphoïde</strong> (réaction des follicules lymphoïdes à un épisode viral ou bactérien).</li></ul>"},{"i":"afcb80518da7","n":356,"o":"356-7","u":"Définition","t":"Connaître la définition de l’appendicite aiguë","q":"Quelle est la définition de l'appendicite aiguë ?","a":"<p>L'appendicite aiguë est une <strong>inflammation aiguë de l'appendice vermiforme</strong>, le plus souvent secondaire à une <strong>obstruction de sa lumière appendiculaire</strong>.</p>"},{"i":"cedea5afcc9d","n":356,"o":"356-9","u":"Diagnostic positif","t":"Connaître les signes d’appel et les caractéristiques de la douleur appendiculaire typique","q":"Quelles sont les caractéristiques principales de la douleur appendiculaire typique de l'appendicite aiguë ?","a":"<p>La douleur appendiculaire typique est une douleur :</p><ul><li>De mode de début <strong>brutal</strong>.</li><li>Qui débute en région <strong>épigastrique ou péri-ombilicale</strong>, puis <strong>migre en fosse iliaque droite</strong> en quelques heures.</li><li><strong>Permanente</strong>, d'intensité croissante sur les premières 24h.</li><li>De type <strong>torsion ou crampe</strong>.</li><li><strong>Majorée</strong> par les mouvements, la toux et le cloche-pied droit.</li></ul>"},{"i":"d8ec01d9d661","n":356,"o":"356-9","u":"Diagnostic positif","t":"Connaître les signes d’appel et les caractéristiques de la douleur appendiculaire typique","q":"Quels sont les signes digestifs et généraux souvent associés à la douleur dans un tableau typique d'appendicite aiguë ?","a":"<p>Les signes associés sont :</p><ul><li><strong>Signes digestifs</strong> : nausées, vomissements, inappétence, diarrhée (rare).</li><li><strong>Signes généraux</strong> : <strong>fébricule à 37,5-38,5 °C</strong> (dans 60% des cas), parfois absent ; et en cas de formes évoluées, des signes de déshydratation (tachycardie, pli cutané, langue saburrale).</li></ul>"},{"i":"f121b1762105","n":356,"o":"356-9","u":"Diagnostic positif","t":"Connaître les signes d’appel et les caractéristiques de la douleur appendiculaire typique","q":"Quels sont les principaux signes à rechercher à l'examen physique de la fosse iliaque droite évoquant une appendicite aiguë ?","a":"<p>Les signes à rechercher sont :</p><ul><li>Le <strong>point de McBurney</strong> positif : douleur provoquée (sensibilité ou défense) au 1/3 externe de la ligne reliant l'épine iliaque antéro-supérieure droite à l'ombilic.</li><li>Le <strong>signe de Blumberg</strong> : douleur en FID à la décompression brutale (inconstant).</li><li>Le <strong>signe de Rovsing</strong> : douleur en FID provoquée par la compression de la fosse iliaque gauche (inconstant).</li><li>Le <strong>psoïtis</strong> : boiterie, cuisse droite fléchie, douleur majorée par l'extension de la cuisse sur le bassin.</li><li>Le <strong>Heel drop test</strong> : douleur abdominale déclenchée par la retombée sur les talons.</li><li>Au <strong>toucher rectal</strong> : douleur latéralisée à droite (cri du Douglas).</li></ul>"}]};